-- Exercise demonstration media + form cues, shown when a user taps an
-- exercise on the Progressie tab (and the Schema tab's day detail). Global
-- reference content, not user data: one row per exercise name from the
-- generator's catalog (packages/program-generator/src/exercises.ts),
-- imported once here rather than fetched live from a third party on every
-- page view.
--
-- Source: free-exercise-db (https://github.com/yuhonas/free-exercise-db),
-- Unlicense (public domain) — no attribution legally required, but the
-- source is recorded per-row anyway for traceability. Chosen over the
-- alternatives researched (ExerciseDB API: AGPL-3.0 + paid tiers + no
-- bundleable media, hotlinked from their CDN; hasaneyldrm/exercises-dataset:
-- MIT for the dataset structure but the media itself is © Gym visual,
-- "redistributed with permission" and NOT freely redistributable — too much
-- licensing risk for media we'd be re-serving) — free-exercise-db is public
-- domain top to bottom, self-hostable (bundled JPGs in the repo, currently
-- referenced via their raw.githubusercontent.com URLs), has both media and
-- textual instructions in one dataset, and needs no API key.
--
-- Matching was done by hand against our own ~70-exercise catalog (not a
-- generic fuzzy-match at runtime): only exact movement+equipment matches
-- were used, so roughly a third of our catalog (mostly Dutch-only variants
-- like "Calf Raise op trede", or exercises this particular dataset simply
-- doesn't have, e.g. plain "Push-up"/"Pull-up") intentionally has no row
-- here — those fall back to the app's plain "not available yet" state
-- instead of showing a mismatched exercise. The "Let op" tips are original
-- Dutch text written for this app (informed by standard lifting-technique
-- knowledge and cross-checked against this dataset's own step-by-step
-- instructions), not a translation of the source's English text.

create table exercise_media (
  id uuid primary key default gen_random_uuid(),
  exercise_name text not null unique,
  media_urls text[] not null,
  tips text[] not null,
  source_name text not null,
  source_url text not null,
  source_license text not null,
  created_at timestamptz not null default now()
);

alter table exercise_media enable row level security;

-- Read-only shared reference content — every authenticated user sees the same
-- rows. No insert/update/delete policy: this table is only ever written by
-- migrations (re-importing is a deliberate, occasional maintenance action,
-- not something the app does at runtime).
create policy "Authenticated users read exercise media" on exercise_media
  for select to authenticated using (true);


